"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["51755"],{58673(e){e.exports=JSON.parse('{"id":"FIN-1208","slug":"gdp-deflator","term":"GDP Deflator","also_known_as":[],"difficulty":"Advanced","definition":"The GDP deflator is a measure of the overall level of prices of all goods and services produced in an economy, calculated by dividing nominal GDP by real GDP and multiplying by 100.","explanation":["Nominal GDP values output at current prices, while real GDP values it at the prices of a base year. The ratio between them shows how much prices have changed since the base year across everything the economy produces.","For example, if nominal GDP is 1,100 and real GDP, measured at base-year prices, is 1,000, the GDP deflator is 110. Prices across the economy are about 10% higher than in the base year.","The GDP deflator differs from the Consumer Price Index. The CPI tracks a fixed basket of goods and services bought by households, including imports. The GDP deflator covers all domestically produced goods and services, including investment goods and government services, and excludes imports. Its weights also change automatically as the mix of output changes.","Because of these differences, the two measures can give different inflation rates. The GDP deflator is useful for understanding price changes across the whole economy, while the CPI is more relevant to the cost of living."],"note":"","total":1500,"prev":{"slug":"gamma","term":"Gamma"},"next":{"slug":"gdp-per-capita","term":"GDP per Capita"}}')}}]);